# ARClass Complete Setup Script
# HOW TO USE:
#   1. Copy this file into D:\Project\ar-classroom-attendance\
#   2. Open PowerShell in that folder
#   3. Run: Set-ExecutionPolicy RemoteSigned -Scope CurrentUser
#   4. Run: .\SETUP.ps1
#   5. Run: node server.js
#   6. Open: http://localhost:3000

$root = Split-Path -Parent $MyInvocation.MyCommand.Definition
Write-Host "`n=== ARClass Setup ===" -ForegroundColor Cyan

function WriteFile($rel, $b64) {
    $full = Join-Path $root $rel
    $dir = Split-Path $full -Parent
    if (!(Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  OK $rel" -ForegroundColor Green
}

